const workerMermaidJS = "const sourceBlocks = document.querySelectorAll(\"pre > code.language-mermaid\");\n\nif (sourceBlocks.length > 0) {\n  const { default: mermaid } = await import(\"https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.esm.min.mjs\");\n  mermaid.initialize({\n    startOnLoad: false,\n    securityLevel: \"strict\",\n    theme: window.matchMedia(\"(prefers-color-scheme: dark)\").matches ? \"dark\" : \"default\",\n    flowchart: { htmlLabels: true, useMaxWidth: true },\n  });\n\n  let diagramNumber = 0;\n  for (const sourceBlock of sourceBlocks) {\n    const source = sourceBlock.textContent;\n    const diagram = document.createElement(\"div\");\n    diagram.className = \"mermaid\";\n    diagram.setAttribute(\"role\", \"img\");\n    diagram.setAttribute(\"aria-label\", \"Mermaid diagram\");\n    sourceBlock.parentElement.replaceWith(diagram);\n\n    try {\n      const { svg, bindFunctions } = await mermaid.render(`mermaid-${diagramNumber++}`, source);\n      diagram.innerHTML = svg;\n      bindFunctions?.(diagram);\n    } catch (error) {\n      console.warn(\"Could not render Mermaid diagram\", error);\n      const fallback = document.createElement(\"pre\");\n      const fallbackCode = document.createElement(\"code\");\n      fallbackCode.className = \"language-mermaid\";\n      fallbackCode.textContent = source;\n      fallback.append(fallbackCode);\n      diagram.replaceWith(fallback);\n    }\n  }\n}\n"

const workerSiteJS = "(() => {\n  const dialog = document.querySelector(\"#command-palette\");\n  const trigger = document.querySelector(\"[data-command-trigger]\");\n  const input = document.querySelector(\"#command-query\");\n  const items = Array.from(document.querySelectorAll(\"[data-command-item]\"));\n  const close = document.querySelector(\"[data-command-close]\");\n  if (!dialog || !trigger || !input || !close) return;\n\n  let activeIndex = 0;\n  const visibleItems = () => items.filter((item) => !item.hidden);\n  const setActive = (index) => {\n    const visible = visibleItems();\n    if (visible.length === 0) return;\n    activeIndex = (index + visible.length) % visible.length;\n    visible.forEach((item, itemIndex) => item.setAttribute(\"aria-selected\", String(itemIndex === activeIndex)));\n  };\n  const filter = () => {\n    const query = input.value.trim().toLocaleLowerCase();\n    items.forEach((item) => {\n      item.hidden = !item.textContent.toLocaleLowerCase().includes(query);\n    });\n    activeIndex = 0;\n    setActive(0);\n  };\n  const open = () => {\n    if (!dialog.open) dialog.showModal();\n    input.value = \"\";\n    filter();\n    input.focus({ preventScroll: true });\n  };\n  const closePalette = () => {\n    if (!dialog.open) return;\n    dialog.close();\n    trigger.focus({ preventScroll: true });\n  };\n\n  trigger.addEventListener(\"click\", open);\n  close.addEventListener(\"click\", closePalette);\n  input.addEventListener(\"input\", filter);\n  input.addEventListener(\"keydown\", (event) => {\n    if (event.key === \"ArrowDown\") {\n      event.preventDefault();\n      setActive(activeIndex + 1);\n    }\n    if (event.key === \"ArrowUp\") {\n      event.preventDefault();\n      setActive(activeIndex - 1);\n    }\n    if (event.key === \"Enter\" && input.value.trim() === \"\") {\n      const item = visibleItems()[activeIndex];\n      if (item) item.click();\n    }\n  });\n  document.addEventListener(\"keydown\", (event) => {\n    const target = event.target;\n    const isTyping = target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement;\n    if ((event.metaKey || event.ctrlKey) && event.key.toLocaleLowerCase() === \"k\") {\n      event.preventDefault();\n      open();\n    }\n    if (event.key === \"/\" && !isTyping && !dialog.open) {\n      event.preventDefault();\n      open();\n    }\n    if (event.key === \"Escape\" && dialog.open) {\n      event.preventDefault();\n      closePalette();\n    }\n  });\n})();\n"
